# -*- coding: utf-8 -*-
import json, os, zipfile, collections, datetime

root = r"D:\GitHub\scrcpy-pad-developing-yaml"
out = []
out.append("now=" + datetime.datetime.now().isoformat())

def mtime(p):
    try:
        return datetime.datetime.fromtimestamp(os.path.getmtime(p)).strftime("%m-%d %H:%M")
    except Exception:
        return "?"

out.append("== root entries ==")
for n in sorted(os.listdir(root)):
    p = os.path.join(root, n)
    kind = "D" if os.path.isdir(p) else "F"
    try:
        sz = os.path.getsize(p)
    except Exception:
        sz = -1
    out.append("%s %12d %12s %r" % (kind, sz, mtime(p), n))

d = os.path.join(root, "文档")
out.append("== 文档 entries ==")
for n in sorted(os.listdir(d)):
    p = os.path.join(d, n)
    out.append("%s %12d %12s %s" % ("D" if os.path.isdir(p) else "F", os.path.getsize(p), mtime(p), n))

zp = os.path.join(root, "dsh对话记录.zip")
out.append("== zip %s (mtime %s) ==" % (zp, mtime(zp)))
z = zipfile.ZipFile(zp)
for i in z.infolist():
    out.append("%12d %s %s" % (i.file_size, i.date_time, i.filename))

name = z.infolist()[0].filename
data = z.read(name).decode("utf-8", "replace")
lines = [l for l in data.splitlines() if l.strip()]
out.append("== %s: %d lines, %d chars ==" % (name, len(lines), len(data)))

types = collections.Counter()
recs = []
bad = 0
for l in lines:
    try:
        o = json.loads(l)
    except Exception:
        bad += 1
        continue
    recs.append(o)
    t = o.get("type")
    if t is None:
        t = "role:" + str(o.get("role"))
    types[str(t)] += 1

out.append("bad-json lines = %d" % bad)
out.append("records = %d" % len(recs))
for k, v in types.most_common():
    out.append("  %-28s %d" % (k, v))

out.append("== first record keys ==")
if recs:
    out.append(json.dumps(list(recs[0].keys()), ensure_ascii=False))
    out.append("SAMPLE: " + json.dumps(recs[0], ensure_ascii=False)[:1200])

def text_of(o):
    # try common shapes
    for k in ("text", "content", "message", "summary"):
        v = o.get(k)
        if isinstance(v, str) and v.strip():
            return v
        if isinstance(v, dict):
            for kk in ("text", "content"):
                if isinstance(v.get(kk), str):
                    return v[kk]
            if isinstance(v.get("content"), list):
                parts = []
                for c in v["content"]:
                    if isinstance(c, dict) and isinstance(c.get("text"), str):
                        parts.append(c["text"])
                if parts:
                    return "\n".join(parts)
        if isinstance(v, list):
            parts = []
            for c in v:
                if isinstance(c, dict) and isinstance(c.get("text"), str):
                    parts.append(c["text"])
            if parts:
                return "\n".join(parts)
    return ""

out.append("== user messages (last 12) ==")
um = [o for o in recs if str(o.get("type", "")) in ("user/message", "user") or o.get("role") == "user"]
out.append("count user-ish = %d" % len(um))
for o in um[-12:]:
    t = text_of(o).replace("\n", " ")
    out.append("--- " + str(o.get("type")) + " " + str(o.get("timestamp", o.get("time", ""))) + " :: " + t[:400])

out.append("== assistant messages (last 4, head 500) ==")
am = [o for o in recs if str(o.get("type", "")) in ("assistant/message", "assistant") or o.get("role") == "assistant"]
out.append("count assistant-ish = %d" % len(am))
for o in am[-4:]:
    t = text_of(o).replace("\n", " ")
    out.append("--- ass :: " + t[:500])

open(r"C:\Users\36124\AppData\Local\Temp\opencode\b4_rec_scan.txt", "w", encoding="utf-8").write("\n".join(out))
print("OK", len(out))

# -*- coding: utf-8 -*-
import json, os, zipfile, datetime

root = r"D:\GitHub\scrcpy-pad-developing-yaml"
out = []

out.append("== raw name bytes (gbk guess) ==")
for b in os.listdir(os.fsencode(root)):
    for enc in ("utf-8", "gbk", "cp936"):
        try:
            s = b.decode(enc)
            break
        except Exception:
            s = None
    if s is None:
        s = repr(b)
    out.append("%-40s | utf8ok=%s" % (s, _ok if False else ""))

out = out[:1]

def decode_name(b):
    for enc in ("utf-8", "gbk", "cp936", "latin-1"):
        try:
            return b.decode(enc), enc
        except Exception:
            continue
    return repr(b), "?"

out.append("== root names (bytes -> best decode) ==")
for b in sorted(os.listdir(os.fsencode(root))):
    s, enc = decode_name(b)
    p = os.path.join(os.fsencode(root), b)
    try:
        sz = os.path.getsize(p)
    except Exception:
        sz = -1
    out.append("%12d  %-6s %r" % (sz, enc, s))

z = zipfile.ZipFile(os.path.join(root, "dsh对话记录.zip"))
