am = [o for o in recs if o.get("type") == "assistant/message"]
for o in am[-2:]:
    out.append(blk(o)[:1500])

out.append("== first 2 tool/call (capped 600) ==")
tc = [o for o in recs if o.get("type") == "tool/call"]
for o in tc[:2]:
    out.append(blk(o)[:600])

out.append("== session/title + session/end-seed + workspace/changes ==")
for o in recs:
    if o.get("type") in ("session/title", "session/end-seed", "workspace/changes", "request/context"):
        out.append(o.get("type") + ": " + blk(o)[:800])

def ts(ms):
    try:
        return datetime.datetime.fromtimestamp(ms / 1000.0).strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return "?"

out.append("== timeline of user messages ==")
for o in recs:
    if o.get("type") == "user/message":
        out.append("%s  %s" % (ts(o.get("createdAt", 0)), blk(o)[:160]))

out.append("== assistant/message count & createdAt range ==")
if am:
    out.append("first=%s last=%s n=%d" % (ts(am[0].get("createdAt", 0)), ts(am[-1].get("createdAt", 0)), len(am)))

open(r"C:\Users\36124\AppData\Local\Temp\opencode\b4_rec_scan2.txt", "w", encoding="utf-8").write("\n".join(out))
print("OK", len(out))

