# -*- coding: utf-8 -*-
import os, json, collections, re

BENCH = r"D:\GitHub\scrcpy-pad-bench\results\12-motion-injection"
OUT = r"C:\Users\36124\AppData\Local\Temp\opencode\b4_align.txt"
out = []

# ---------- A: alignment r6-c ----------
B = os.path.join(BENCH, "blocks", "r6-c-rawoff-accon")
csvs = [f for f in os.listdir(B) if f.endswith(".csv")]
out.append("csv files in block: %r" % csvs)
app = []
btns = []
for line in open(os.path.join(B, "trace-slice.jsonl"), encoding="utf-8", errors="replace"):
    if '"e":"motion"' in line or '"e":"btn"' in line:
        try:
            o = json.loads(line)
        except Exception:
            continue
        if o.get("e") == "motion":
            app.append((int(o["t"]), int(o["dx"])))
        else:
            btns.append(line.strip()[:260])
out.append("app motion events: %d" % len(app))
out.append("in/btn lines (%d):" % len(btns))
for b in btns:
    out.append("   | " + b)

if csvs:
    p = os.path.join(B, csvs[0])
    lines = open(p, encoding="utf-8", errors="replace").read().splitlines()
    out.append("csv head: %r" % lines[:4])
    hdr = [c.strip().lower() for c in lines[0].split(",")]
    di = hdr.index("dx") if "dx" in hdr else None
    rows = []
    if di is None:
        out.append("no dx column; header=%r" % hdr)
    else:
        for ln in lines[1:]:
            parts = ln.split(",")
            if len(parts) <= di:
                continue
            try:
                rows.append(int(float(parts[di])))
            except Exception:
                pass
        out.append("csv rows=%d sum_dx=%d first20=%r last5=%r" % (len(rows), sum(rows), rows[:20], rows[-5:]))
        for off, label in ((0, "app[i]~csv[i]"), (1, "app[i+1]~csv[i]"), (-1, "app[i]~csv[i+1]")):
            n = 0
            agree = 0
            for i in range(min(len(rows), len(app))):
                a_i = i + off
                if a_i < 0 or a_i >= len(app):
                    continue
                n += 1
                if (app[a_i][1] > 0) == (rows[i] > 0):
                    agree += 1
            out.append("align %-14s n=%d sign_agree=%d (%.4f)" % (label, n, agree, agree / max(n, 1)))
        bigpos = collections.Counter()
        allpos = collections.Counter()
        big_pairs = []
        ebig = 0
        for i in range(min(len(rows), len(app))):
            d = app[i][1]
            pos = i % 500
            allpos[pos // 100] += 1
            if abs(d) > 100:
                bigpos[pos // 100] += 1
                if len(big_pairs) < 14:
                    big_pairs.append((i, rows[i], d))
            if (pos < 10 or pos >= 490) and abs(d) > 100:
                ebig += 1
        out.append("big by pos//100: %r ; all: %r" % (sorted(bigpos.items()), sorted(allpos.items())))
        out.append("big at block edges (pos<10 or >=490): %d" % ebig)
        out.append("first big pairs (i, inj_dx, app_dx): %r" % big_pairs)
        bins = collections.Counter()
        for t, d in app:
            if abs(d) > 100:
                bins[t // 1000] += 1
        out.append("big/s by second: %r" % sorted(bins.items()))

# ---------- B: per-block diagnostics + slice kinds ----------
out.append("")
out.append("== per block: diagnostics 积压/WARN + slice kinds ==")
base = os.path.join(BENCH, "blocks")
for b in sorted(os.listdir(base)):
    d = os.path.join(base, b)
    if not os.path.isdir(d):
        continue
    p = os.path.join(d, "diagnostics.log")
    warn = 0
    jam = 0
    dropmax = 0
    lines = 0
    if os.path.exists(p):
        for line in open(p, encoding="utf-8", errors="replace"):
            lines += 1
            if "WARN" in line or "ERROR" in line:
                warn += 1
            if "积压" in line:
                jam += 1
                m = re.search(r"累计丢弃 (\d+) 条", line)
                if m:
                    dropmax = max(dropmax, int(m.group(1)))
    out.append("[%s] diag lines=%d WARN=%d 积压=%d dropmax=%d" % (b, lines, warn, jam, dropmax))
    sp = os.path.join(d, "trace-slice.jsonl")
    if os.path.exists(sp):
        k = collections.Counter()
        for line in open(sp, encoding="utf-8", errors="replace"):
            try:
                o = json.loads(line)
            except Exception:
                continue
            k["%s/%s" % (o.get("k"), o.get("e", ""))] += 1
        out.append("    slice kinds: %s" % ", ".join("%s=%d" % kv for kv in sorted(k.items())))
    else:
        out.append("    (no trace-slice.jsonl)")

# ---------- C: aim peek ----------
for line in open(os.path.join(B, "trace-slice.jsonl"), encoding="utf-8", errors="replace"):
    if '"e":"aim"' in line:
        out.append("aim sample: " + line.strip()[:400])
        break

open(OUT, "w", encoding="utf-8").write("\n".join(out))
print("OK")

